{"kind":"stack","id":"s-human-dev","title":"Human development: from birth to old age","theme":{"background":"#f4f9ff","foreground":"#1f2a44","font":"Arial, sans-serif"}}
{"kind":"card","card":{"id":"c1","kind":"quiz","elements":[{"type":"text","id":"c1-q","content":"What is the first stage of human life?"},{"type":"button","id":"c1-a","label":"Infancy","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c2"}]},{"type":"button","id":"c1-b","label":"Old age","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c2"}]},{"type":"button","id":"c1-c","label":"Adulthood","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c2"}]}],"actions":[]}}
