{"kind":"card","card":{"id":"c8","kind":"flash","elements":[{"type":"text","id":"c8-t","content":"Puberty"},{"type":"text","id":"c8-e","content":"Puberty is the stage when the body changes and becomes able to have children."},{"type":"button","id":"c8-n","label":"Next Card","actions":[{"type":"goto","cardId":"c9"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c9","kind":"quiz","elements":[{"type":"text","id":"c9-q","content":"Which stage comes after adolescence?"},{"type":"button","id":"c9-a","label":"Adulthood","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-b","label":"Infancy","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-c","label":"Toddlerhood","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]}],"actions":[]}}
